import dormbr = require( './index' );


// TESTS //

// The function returns a number...
{
	const A = new Float64Array( 3 );
	const TAU = new Float64Array( 1 );
	const C = new Float64Array( 6 );
	const WORK = new Float64Array( 3 );

	dormbr( 'row-major', 'Q', 'left', 'no-transpose', 2, 3, 1, A, 2, TAU, C, 3, WORK, 3 ); // $ExpectType number
	dormbr( 'column-major', 'P', 'right', 'transpose', 2, 3, 1, A, 2, TAU, C, 3, WORK, 3 ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a valid layout...
{
	const A = new Float64Array( 3 );
	const TAU = new Float64Array( 1 );
	const C = new Float64Array( 6 );
	const WORK = new Float64Array( 3 );

	dormbr( 5, 'Q', 'left', 'no-transpose', 2, 3, 1, A, 2, TAU, C, 3, WORK, 3 ); // $ExpectError
	dormbr( true, 'Q', 'left', 'no-transpose', 2, 3, 1, A, 2, TAU, C, 3, WORK, 3 ); // $ExpectError
	dormbr( false, 'Q', 'left', 'no-transpose', 2, 3, 1, A, 2, TAU, C, 3, WORK, 3 ); // $ExpectError
	dormbr( null, 'Q', 'left', 'no-transpose', 2, 3, 1, A, 2, TAU, C, 3, WORK, 3 ); // $ExpectError
	dormbr( void 0, 'Q', 'left', 'no-transpose', 2, 3, 1, A, 2, TAU, C, 3, WORK, 3 ); // $ExpectError
	dormbr( [], 'Q', 'left', 'no-transpose', 2, 3, 1, A, 2, TAU, C, 3, WORK, 3 ); // $ExpectError
	dormbr( {}, 'Q', 'left', 'no-transpose', 2, 3, 1, A, 2, TAU, C, 3, WORK, 3 ); // $ExpectError
	dormbr( ( x: number ): number => x, 'Q', 'left', 'no-transpose', 2, 3, 1, A, 2, TAU, C, 3, WORK, 3 ); // $ExpectError
}

