// Attached to the main export is an `ndarray` method which returns a number...
{
	const A = new Float64Array( 3 );
	const TAU = new Float64Array( 1 );
	const C = new Float64Array( 6 );
	const WORK = new Float64Array( 3 );

	dormbr.ndarray( 'Q', 'left', 'no-transpose', 2, 3, 1, A, 2, 1, 0, TAU, 1, 0, C, 3, 1, 0, WORK, 1, 0, 3 ); // $ExpectType number
	dormbr.ndarray( 'P', 'right', 'transpose', 2, 3, 1, A, 2, 1, 0, TAU, 1, 0, C, 3, 1, 0, WORK, 1, 0, 3 ); // $ExpectType number
}

